// Ported from flying-saucer-core/src/test/java/org/xhtmlrenderer/layout/CounterFunctionTest.java
//
// TestCounterFunctionCreateCounterTextAgainstJava compares against values
// produced by running the Java CounterFunction over the same inputs.

package ufo

import (
	"strings"
	"testing"
)

func counterFunctionTestCheck(t *testing.T, style *IdentValue, value int, want string) {
	t.Helper()
	if got := CounterFunctionCreateCounterText(style, value); got != want {
		t.Errorf("CounterFunctionCreateCounterText(%s, %d) = %q, want %q", style, value, got, want)
	}
}

func TestCounterFunctionLowerLatin(t *testing.T) {
	for _, style := range []*IdentValue{IdentValueLowerAlpha, IdentValueLowerLatin} {
		counterFunctionTestCheck(t, style, 0, "")
		counterFunctionTestCheck(t, style, 1, "a")
		counterFunctionTestCheck(t, style, 2, "b")
		counterFunctionTestCheck(t, style, 5, "e")
		counterFunctionTestCheck(t, style, 25, "y")
		counterFunctionTestCheck(t, style, 26, "z")
		counterFunctionTestCheck(t, style, 27, "aa")
		counterFunctionTestCheck(t, style, 28, "ab")
		counterFunctionTestCheck(t, style, 26*26-1, "yy")
		counterFunctionTestCheck(t, style, 26*26, "yz")
		counterFunctionTestCheck(t, style, 26*27, "zz")
	}
}

func TestCounterFunctionUpperLatin(t *testing.T) {
	for _, style := range []*IdentValue{IdentValueUpperAlpha, IdentValueUpperLatin} {
		counterFunctionTestCheck(t, style, 1, "A")
		counterFunctionTestCheck(t, style, 7, "G")
		counterFunctionTestCheck(t, style, 26, "Z")
		counterFunctionTestCheck(t, style, 27, "AA")
		counterFunctionTestCheck(t, style, 28, "AB")
		counterFunctionTestCheck(t, style, 27*2, "BB")
		counterFunctionTestCheck(t, style, 27*3, "CC")
		counterFunctionTestCheck(t, style, 26*26, "YZ")
		counterFunctionTestCheck(t, style, 26*27, "ZZ")
	}
}

func TestCounterFunctionLowerRoman(t *testing.T) {
	counterFunctionTestCheck(t, IdentValueLowerRoman, 0, "")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 1, "i")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 2, "ii")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 5, "v")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 10, "x")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 49, "xlix")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 50, "l")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 51, "li")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 99, "xcix")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 100, "c")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 104, "civ")
	// CM = 900, XC = 90, VIII = 8
	counterFunctionTestCheck(t, IdentValueLowerRoman, 998, "cmxcviii")
	counterFunctionTestCheck(t, IdentValueLowerRoman, 1003, "miii")
}

func TestCounterFunctionUpperRoman(t *testing.T) {
	counterFunctionTestCheck(t, IdentValueUpperRoman, 1, "I")
	counterFunctionTestCheck(t, IdentValueUpperRoman, 4, "IV")
	counterFunctionTestCheck(t, IdentValueUpperRoman, 6, "VI")
	counterFunctionTestCheck(t, IdentValueUpperRoman, 47, "XLVII")
	// XL = 40, VIII = 8
	counterFunctionTestCheck(t, IdentValueUpperRoman, 48, "XLVIII")
	// XL = 40, IX = 9
	counterFunctionTestCheck(t, IdentValueUpperRoman, 49, "XLIX")
	counterFunctionTestCheck(t, IdentValueUpperRoman, 50, "L")
	// XC = 90, IX = 9
	counterFunctionTestCheck(t, IdentValueUpperRoman, 99, "XCIX")
	counterFunctionTestCheck(t, IdentValueUpperRoman, 101, "CI")
	counterFunctionTestCheck(t, IdentValueUpperRoman, 500, "D")
	counterFunctionTestCheck(t, IdentValueUpperRoman, 1002, "MII")
}

func TestCounterFunctionDecimalLeadingZero(t *testing.T) {
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 1, "01")
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 2, "02")
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 9, "09")
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 10, "10")
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 11, "11")
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 99, "99")
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 100, "100")
	counterFunctionTestCheck(t, IdentValueDecimalLeadingZero, 1002, "1002")
}

func TestCounterFunctionDefaultStyleIsDisk(t *testing.T) {
	for _, style := range []*IdentValue{IdentValueDecimal, IdentValueDisc, IdentValueCircle, IdentValueSquare} {
		counterFunctionTestCheck(t, style, 1, "1")
		counterFunctionTestCheck(t, style, 7, "7")
		counterFunctionTestCheck(t, style, 8888, "8888")
	}
}

func TestCounterFunctionEvaluate_lowerRoman(t *testing.T) {
	function := NewCounterFunction(7, IdentValueLowerRoman)
	if got := function.Evaluate(); got != "vii" {
		t.Errorf("got %q", got)
	}
}

func TestCounterFunctionEvaluate_upperLatin(t *testing.T) {
	function := NewCounterFunction(8, IdentValueUpperLatin)
	if got := function.Evaluate(); got != "H" {
		t.Errorf("got %q", got)
	}
}

func TestCounterFunctionEvaluate_lowerGreek(t *testing.T) {
	tests := []struct {
		index    int
		expected string
	}{
		{1, "α"}, {2, "β"}, {3, "γ"}, {4, "δ"}, {5, "ε"}, {6, "ζ"}, {7, "η"}, {8, "θ"},
		{9, "ι"}, {10, "κ"}, {11, "λ"}, {12, "μ"}, {13, "ν"}, {14, "ξ"}, {15, "ο"}, {16, "π"},
		{17, "ρ"}, {18, "σ"}, {19, "τ"}, {20, "υ"}, {21, "φ"}, {22, "χ"}, {23, "ψ"}, {24, "ω"},
		{25, "αα"}, {26, "αβ"}, {48, "αω"}, {600, "ωω"},
	}
	for _, tt := range tests {
		function := NewCounterFunction(tt.index, IdentValueLowerGreek)
		if got := function.Evaluate(); got != tt.expected {
			t.Errorf("%d: got %q, want %q", tt.index, got, tt.expected)
		}
	}
}

func TestCounterFunctionEvaluate_upperGreek(t *testing.T) {
	tests := []struct {
		index    int
		expected string
	}{
		{1, "Α"}, {2, "Β"}, {3, "Γ"}, {4, "Δ"}, {5, "Ε"}, {6, "Ζ"}, {7, "Η"}, {8, "Θ"},
		{9, "Ι"}, {10, "Κ"}, {11, "Λ"}, {12, "Μ"}, {13, "Ν"}, {14, "Ξ"}, {15, "Ο"}, {16, "Π"},
		{17, "Ρ"}, {18, "Σ"}, {19, "Τ"}, {20, "Υ"}, {21, "Φ"}, {22, "Χ"}, {23, "Ψ"}, {24, "Ω"},
		{25, "ΑΑ"}, {48, "ΑΩ"}, {600, "ΩΩ"},
	}
	for _, tt := range tests {
		function := NewCounterFunction(tt.index, IdentValueUpperGreek)
		if got := function.Evaluate(); got != tt.expected {
			t.Errorf("%d: got %q, want %q", tt.index, got, tt.expected)
		}
	}
}

// counterFunctionTestValues are the counter values of every row of
// TestCounterFunctionCreateCounterTextAgainstJava, in order.
var counterFunctionTestValues = []int{
	-1500, -1001, -100, -30, -26, -25, -24, -10, -9, -1, 0, 1,
	2, 3, 4, 5, 9, 10, 11, 14, 19, 24, 25, 26,
	27, 28, 40, 48, 49, 50, 52, 53, 72, 73, 80, 99,
	100, 101, 499, 500, 600, 649, 650, 675, 676, 677, 701, 702,
	703, 704, 998, 1003, 3999, 4000, 5000, 9999, 18278, 18279, 100000, 2147483647,
}

// TestCounterFunctionCreateCounterTextAgainstJava: want holds the Java result
// for each of counterFunctionTestValues, separated by "|". The list style
// types that the Java class does not implement (armenian, georgian, hebrew,
// the CJK and kana types, the bullet types, none) give the decimal number.
